/// <reference path="template.ts" />
/// <reference lib="es2015.promise" />

// Some portions generated by Codex
namespace workbench {
    export namespace backups {
        export function isRunning(job: any): boolean {
            return !!job && job.state === 'RUNNING';
        }
        export function validTarget(id: string, source: string): boolean {
            return /^[A-Za-z0-9][A-Za-z0-9_-]*$/.test(id) && id !== source;
        }
        /** Dispose stops polling; textContent prevents backup names and failure messages injecting markup. */
        export function mount(outlet: HTMLElement, ctx: any): () => void {
            const document = outlet.ownerDocument;
            const host = outlet.querySelector('#backups-content');
            const endpoint = new URL(ctx.url.href);
            endpoint.search = ''; endpoint.hash = '';
            let disposed = false;
            let timer: any;
            let request: AbortController = null;
            let generation = 0;
            let snapshot: any = null;
            let pending = false;
            let error = '';
            let renderedState = '';
            function element(tag: string, value?: any): HTMLElement {
                const node = document.createElement(tag);
                if (value !== undefined) node.textContent = String(value);
                return node;
            }
            function button(label: string, action: () => void, disabled: boolean, key: string = label): HTMLButtonElement {
                const node = element('button', label) as HTMLButtonElement;
                node.type = 'button'; node.disabled = disabled;
                node.setAttribute('data-backup-control', key);
                node.addEventListener('click', action);
                return node;
            }
            function render(): void {
                if (disposed) return;
                const state = JSON.stringify([snapshot, pending, error]);
                if (state === renderedState) return;
                renderedState = state;
                const focused = document.activeElement;
                const focusKey = focused && host.contains && host.contains(focused)
                    ? focused.getAttribute('data-backup-control') : null;
                try {
                    host.textContent = '';
                    if (error) {
                        const message = element('p', error); message.setAttribute('role', 'alert'); host.appendChild(message);
                    }
                    if (!snapshot) { host.appendChild(element('p', error ? 'Status could not be loaded.' : 'Loading backup status…')); return; }
                    if (!snapshot.supported) {
                        host.appendChild(element('p', 'Backup management is unavailable. It requires a supported LMDB repository on RDF4J Server.')); return;
                    }
                    const busy = pending || isRunning(snapshot.job) || !!snapshot.activeOperation;
                    host.appendChild(button('Create full backup', () => submit({action:'backup'}), busy));
                    host.appendChild(button('Refresh', refresh, pending));
                    const active = snapshot.activeOperation;
                    const activity = element('p', active ? 'Storage operation: ' + active.operation + ' — ' + active.phase
                        + ' (started ' + active.startedAt + ')' : 'No storage backup operation is running.');
                    activity.setAttribute('role', 'status');
                    activity.setAttribute('data-backup-control', 'activity-status');
                    activity.setAttribute('tabindex', '-1'); host.appendChild(activity);
                    const status = element('p', snapshot.job ? 'Workbench-managed operation: ' + snapshot.job.operation + ' — ' + snapshot.job.state
                        + (snapshot.job.message ? '. ' + snapshot.job.message : '') : 'No Workbench-managed operation has run in this server session.');
                    status.setAttribute('role', 'status'); host.appendChild(status);
                    host.appendChild(element('p', 'Backups are stored on the server. Restore creates a new repository and leaves this repository unchanged. Storage activity includes scheduled and directly started operations for this repository. The verification flag is recorded metadata; restore checks the snapshot checksum. Progress is shown by phase, not percentage.'));
                    if (snapshot.job && snapshot.job.targetRepositoryId && snapshot.job.state === 'SUCCEEDED') {
                        host.appendChild(element('p', 'Restored repository: ' + snapshot.job.targetRepositoryId));
                    }
                    const table = element('table'); const head = element('tr');
                    ['Backup', 'Created', 'Type', 'Transaction', 'Verification flag', 'Restore'].forEach((title) => head.appendChild(element('th', title)));
                    const thead = element('thead'); thead.appendChild(head); table.appendChild(thead);
                    const body = element('tbody');
                    (snapshot.backups || []).forEach((backup: any) => {
                        const row = element('tr');
                        [backup.id, backup.createdAt, backup.type, backup.endTransactionId, backup.verified ? 'Yes' : 'No'].forEach((value: any) => row.appendChild(element('td', value)));
                        const cell = element('td'); cell.appendChild(button('Restore to new repository', () => restore(backup.id), busy, 'restore:' + backup.id));
                        row.appendChild(cell); body.appendChild(row);
                    });
                    table.appendChild(body); host.appendChild(table);
                    if (!(snapshot.backups || []).length) host.appendChild(element('p', 'No backups available.'));
                } finally {
                    if (focusKey) {
                        const controls = host.querySelectorAll('[data-backup-control]');
                        let replacement: HTMLButtonElement = null;
                        for (let i = 0; i < controls.length; i++) {
                            const control = controls[i] as HTMLButtonElement;
                            if (control.getAttribute('data-backup-control') === focusKey && !control.disabled) replacement = control;
                        }
                        if (replacement) replacement.focus();
                        else {
                            const status = host.querySelector('[role="status"]') as HTMLElement;
                            if (status) { status.setAttribute('tabindex', '-1'); status.focus(); }
                        }
                    }
                }
            }
            function restore(id: string): void {
                const source = decodeURIComponent(endpoint.pathname.split('/').slice(-2)[0]);
                const target = window.prompt('New repository ID (letters, digits, hyphen or underscore). The existing repository will not be changed.');
                if (target === null) return;
                if (!validTarget(target, source)) { error = 'Choose a different, valid repository ID.'; render(); return; }
                if (window.confirm('Restore backup ' + id + ' into new repository “' + target + '”?')) submit({action:'restore', backupId:id, targetRepositoryId:target});
            }
            function schedule(token: number): void {
                if (!disposed && generation === token) { clearTimeout(timer); timer = setTimeout(refresh, 3000); }
            }
            function start(): number {
                clearTimeout(timer); if (request) request.abort();
                request = new AbortController(); return ++generation;
            }
            function refresh(): void {
                if (disposed || pending) return;
                const token = start();
                const url = new URL(endpoint.href); url.searchParams.set('action','status');
                fetch(url.href, {credentials:'same-origin', signal:request.signal, headers:{Accept:'application/json'}})
                    .then((response) => { if (!response.ok) throw new Error('Backup status unavailable (HTTP ' + response.status + ').'); return response.json(); })
                    .then((data) => { if (!disposed && generation === token) { snapshot = data; error = ''; render(); } })
                    .catch((failure) => { if (!disposed && generation === token && failure.name !== 'AbortError') { error = failure.message; render(); } })
                    .then(() => schedule(token));
            }
            function submit(values: {[key: string]: string}): void {
                if (disposed || pending || (snapshot && (isRunning(snapshot.job) || snapshot.activeOperation))) return;
                const token = start(); pending = true; error = ''; render();
                const body = new URLSearchParams(); Object.keys(values).forEach((key) => body.set(key, values[key]));
                fetch(endpoint.href, {method:'POST', credentials:'same-origin', body, signal:request.signal,
                    headers:Object.assign({'Accept':'application/json'}, workbench.csrfHeaders(endpoint.href))})
                    .then((response) => { if (!response.ok) throw new Error('HTTP ' + response.status); return response.json(); })
                    .then((job) => { if (!disposed && generation === token) snapshot.job = job; })
                    .catch((failure) => { if (!disposed && generation === token && failure.name !== 'AbortError') error = 'Could not confirm whether the operation was accepted (' + failure.message + '). Refresh status before retrying.'; })
                    .then(() => { pending = false; if (!disposed && generation === token) { render(); schedule(token); } });
            }
            render(); refresh();
            return () => { disposed = true; ++generation; clearTimeout(timer); if (request) request.abort(); };
        }
    }
}
